'use client';

import { useState } from 'react';
import { useAuth } from '@/context/AuthContext';
import { api } from '@/lib/api';
import { Building2, Plus, X } from 'lucide-react';

export default function TenantsPage() {
    const { user } = useAuth();
    const [tenants, setTenants] = useState<any[]>([]);
    const [showForm, setShowForm] = useState(false);
    const [form, setForm] = useState({ name: '', code: '', subscription_plan: 'starter' });
    const [loaded, setLoaded] = useState(false);

    const loadTenants = async () => {
        try {
            const res = await api.get<any[]>('/api/admin/tenants');
            if (res.success) setTenants(res.data);
        } catch (e) { }
        setLoaded(true);
    };

    if (!loaded) loadTenants();

    const handleCreate = async () => {
        try {
            await api.post('/api/admin/tenants', form);
            setShowForm(false);
            setForm({ name: '', code: '', subscription_plan: 'starter' });
            loadTenants();
        } catch (e) { }
    };

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
                <div>
                    <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins' }}>Institutions</h1>
                    <p style={{ fontSize: 14, color: '#5a6a72' }}>Manage all onboarded institutions</p>
                </div>
                <button className="btn-primary" onClick={() => setShowForm(true)}>
                    <Plus size={16} /> Add Institution
                </button>
            </div>

            {showForm && (
                <div className="card" style={{ marginBottom: 24, padding: 28 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 16 }}>
                        <h3 style={{ fontSize: 16, fontWeight: 700, color: '#142B34' }}>New Institution</h3>
                        <button onClick={() => setShowForm(false)} style={{ background: 'none', border: 'none', cursor: 'pointer' }}>
                            <X size={18} color="#8a9aa2" />
                        </button>
                    </div>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 16 }}>
                        <div className="form-group">
                            <label>Name</label>
                            <input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="Alpha University" />
                        </div>
                        <div className="form-group">
                            <label>Code</label>
                            <input value={form.code} onChange={(e) => setForm({ ...form, code: e.target.value })} placeholder="ALPHA" />
                        </div>
                        <div className="form-group">
                            <label>Plan</label>
                            <select value={form.subscription_plan} onChange={(e) => setForm({ ...form, subscription_plan: e.target.value })}>
                                <option value="starter">Starter</option>
                                <option value="professional">Professional</option>
                                <option value="enterprise">Enterprise</option>
                            </select>
                        </div>
                    </div>
                    <button className="btn-primary" onClick={handleCreate}>Create Institution</button>
                </div>
            )}

            <div className="table-container">
                <table>
                    <thead>
                        <tr>
                            <th>Name</th>
                            <th>Code</th>
                            <th>Plan</th>
                            <th>Status</th>
                        </tr>
                    </thead>
                    <tbody>
                        {tenants.length === 0 ? (
                            <tr><td colSpan={4} style={{ textAlign: 'center', padding: 32, color: '#8a9aa2' }}>No institutions yet. Click "Add Institution" to create one.</td></tr>
                        ) : tenants.map((t) => (
                            <tr key={t.id}>
                                <td style={{ fontWeight: 600 }}>{t.name}</td>
                                <td><code style={{ fontSize: 13, background: '#f3f4f6', padding: '2px 8px', borderRadius: 4 }}>{t.code}</code></td>
                                <td><span className="badge badge-info">{t.subscription_plan}</span></td>
                                <td><span className={`badge ${t.is_active ? 'badge-success' : 'badge-danger'}`}>{t.is_active ? 'Active' : 'Disabled'}</span></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}
